def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.22
        if no_water_days >= 2 or hp <= 3:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    max_prev = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
            if float(pbid) > max_prev:
                max_prev = float(pbid)
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            urgent_opp += 1
        if opp.get('budget', 0) >= 700:
            rich_opp += 1

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    pressure = 0.38 + 0.22 * scarcity + 0.08 * urgent_opp + 0.04 * rich_opp
    if max_prev >= 90:
        pressure += 0.08
    elif max_prev >= 75:
        pressure += 0.05
    elif max_prev <= 45:
        pressure -= 0.04

    self_urgency = 0
    if no_water_days >= 2:
        self_urgency += 2
    elif no_water_days == 1:
        self_urgency += 1
    if hp <= 2:
        self_urgency += 2
    elif hp <= 4:
        self_urgency += 1

    pressure += 0.14 * self_urgency

    if day >= 8 and hp > 5 and no_water_days == 0:
        pressure -= 0.05

    if supply >= 23 and self_urgency == 0:
        pressure -= 0.08
    elif supply <= 17:
        pressure += 0.08

    if pressure < 0.18:
        pressure = 0.18
    if pressure > 0.98:
        pressure = 0.98

    bid = DAILY_SALARY * pressure

    if prev_bids and self_urgency > 0:
        target = max_prev + 1.5
        if target > bid:
            bid = target

    if self_urgency == 0 and max_prev >= 85 and supply >= 20:
        bid = min(bid, DAILY_SALARY * 0.34)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = DAILY_SALARY * 2.0
    elif day <= 9:
        reserve_floor = DAILY_SALARY * 1.0

    affordable = budget
    if budget > reserve_floor:
        affordable = budget - reserve_floor + min(reserve_floor * 0.25, DAILY_SALARY * 0.5)

    if self_urgency >= 3:
        affordable = budget

    bid = min(bid, affordable, budget)
    if self_urgency >= 3:
        bid = max(bid, DAILY_SALARY * 0.82)
    elif self_urgency == 2:
        bid = max(bid, DAILY_SALARY * 0.68)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target = min(my_status['budget'], avg_prev * 1.05)
        return max(target, 25.0)

    return min(my_status['budget'], 40.0)
